using System;using System.Linq;using System.IO;using System.Text;using System.Collections.Generic;using System.Runtime.Serialization.Json;using GlassBoard;
class PersonalizationTests {
    static int count;static void Check(bool value,string name){count++;if(!value)throw new Exception(name);}
    static T Json<T>(T item){using(var s=new MemoryStream()){var j=new DataContractJsonSerializer(typeof(T));j.WriteObject(s,item);s.Position=0;return (T)j.ReadObject(s);}}
    static T Read<T>(string json){using(var s=new MemoryStream(Encoding.UTF8.GetBytes(json)))return (T)new DataContractJsonSerializer(typeof(T)).ReadObject(s);}
    static int Main(){
        foreach(double center in new[]{500.0,960,-960})foreach(double width in new[]{300.0,700,900}){double left=DockAnchorRules.Left(center,width,0,center-960,1920);Check(Math.Abs(left+width/2-center)<.001,"Dock center stable after resize/switch and on negative monitor");}
        Check(DockAnchorRules.Left(10,500,0,0,1920)==0,"left screen clamp");Check(DockAnchorRules.Left(1900,500,0,0,1920)==1420,"right screen clamp");
        var p=new Preferences();p.Normalize();foreach(string kind in WidgetRules.Kinds){var s=p.Widgets.Style(kind);s.TextColor="#00CCFF";s.TextOpacity=77;s.Frameless=true;s.TextShadow=true;s.ClockStyle=1;s.MusicButtons=4;s.Font="Segoe Script";s.ClockSize=62;s.ShowDate=false;s.Hour24=false;}
        p.Placement.DockLeft=200;p.Placement.DockCenter=550;p.Dock.ShowPower=p.Dock.ShowNetwork=true;
        var saved=Json(p);saved.Normalize();Check(saved.Placement.DockCenter==550&&saved.Dock.ShowPower&&saved.Dock.ShowNetwork,"Dock anchor and quick actions persist");foreach(string kind in WidgetRules.Kinds)Check(saved.Widgets.Style(kind).Signature()==p.Widgets.Style(kind).Signature(),"all per-widget DIY fields survive restart");
        var copy=p.Widgets.Copy();copy.Style("clock").TextColor="#FFFFFF";Check(p.Widgets.Style("clock").TextColor=="#00CCFF","copy does not mutate original DIY");
        var target=new Preferences();FeatureRules.Apply(target,Json(FeatureRules.Capture(p,"DIY")));Check(target.Widgets.Style("music").MusicButtons==4&&target.Widgets.Style("notes").Frameless,"appearance scheme retains DIY");
        var old=Read<Preferences>("{}");old.Normalize();Check(old.Widgets.Style("clock").TextOpacity==100&&!old.Widgets.Style("clock").Frameless&&old.Widgets.Style("clock").ShowDate&&!old.Dock.ShowPower,"legacy defaults preserve existing layout");
        var s1=Read<WidgetStyle>("{\"Kind\":\"clock\"}");s1.Normalize();Check(s1.Hour24&&s1.ClockSize==48&&s1.TextOpacity==100,"missing serialized style values initialize");
        Check(s1.WeatherStyle==0&&!s1.WeatherShowPlace&&!s1.WeatherShowDetails&&s1.ShowAmPm,"legacy config defaults and compact defaults");var compact=new WidgetStyle{Kind="weather",WeatherStyle=1,WeatherShowPlace=true,WeatherShowDetails=true,ShowAmPm=false};var compactSaved=Json(compact);Check(compactSaved.Signature()==compact.Signature(),"new appearance options persist");compactSaved.WeatherStyle=99;compactSaved.Normalize();Check(compactSaved.WeatherStyle==1,"weather style is bounded");
        s1.TextColor="bad!";s1.TextOpacity=double.NaN;s1.ClockSize=double.PositiveInfinity;s1.Normalize();Check(s1.TextColor==""&&s1.TextOpacity==100&&s1.ClockSize==48,"malformed style safely normalizes");Check(WidgetStyle.Color("abcdef")=="#ABCDEF","HEX validation");
        p.Widgets.Styles.Add(new WidgetStyle{Kind="unknown"});p.Widgets.Styles.Add(new WidgetStyle{Kind="clock"});p.Widgets.Normalize();Check(p.Widgets.Styles.Count==4,"unknown and duplicate styles removed");
        var dock=new DockOptions();double before=dock.WidthFor(5);dock.ShowPower=dock.ShowNetwork=true;Check(dock.WidthFor(5)>before&&dock.VisiblePinned(500,20)<new DockOptions().VisiblePinned(500,20),"quick action slots included in overflow sizing");
        Check(WeatherPresentation.Description(-1,"Heavy rain")=="大雨"&&WeatherPresentation.Icon(-1,"Heavy rain")=="rain","English heavy rain translated and rain icon");Check(WeatherPresentation.Icon(95,null)=="storm"&&WeatherPresentation.Icon(75,null)=="snow"&&WeatherPresentation.Icon(45,null)=="fog","WMO weather glyph classification");
        Check(WeatherPresentation.Icon(0,null)=="sun"&&WeatherPresentation.Icon(-1,null)=="cloud","unknown is never sunny");Check(WeatherPresentation.Description(-1,"Clear")=="晴"&&WeatherPresentation.Description(-1,"雨夹雪")=="雨夹雪","clear and existing Chinese");
        Check(WeatherPresentation.Place("济南市",new GeoPlace{Name="Hongjialou",Country="China"})=="济南","retain requested city instead of nearby landmark");Check(WeatherPresentation.Place("30,120",new GeoPlace{Name="杭州"})=="杭州","coordinates show resolved locality");
        string data="{\"current_condition\":[{\"temp_C\":\"18\",\"windspeedKmph\":\"4\",\"lang_xx\":[{\"value\":\"大雨\"}],\"weatherDesc\":[{\"value\":\"Heavy rain\"}]}],\"nearest_area\":[{\"areaName\":[{\"value\":\"Hongjialou\"}],\"country\":[{\"value\":\"China\"}],\"latitude\":\"36.7\",\"longitude\":\"117.0\"}]}";
        var reply=Read<WttrReply>(data);Check(WeatherClient.FromWttr(reply).Current.Description=="大雨","new lang_xx field supported");reply.Current[0].Localized=null;Check(WeatherClient.FromWttr(reply).Current.Description=="大雨","local translation when provider Chinese missing");
        Check(BackgroundWorkRules.MediaPollSeconds(false,true,true)>BackgroundWorkRules.MediaPollSeconds(true,true,true),"hidden music reduced polling");Check(BackgroundWorkRules.MediaPollSeconds(true,false,false)>BackgroundWorkRules.MediaPollSeconds(true,true,true),"no-player reduced polling");
        Console.WriteLine("PASS: "+count+" checks: fixed center, boundaries, restart/legacy/copy/scheme DIY, overflow slots, Chinese weather/landmark/lang_xx, adaptive polling.");return 0;
    }
}
